    "instructionKey": "instruksi",
    "locale": {
      "id": {
        "judul": "Satuan untuk Mengukur",
        "instruksi": "Panjang memakai cm, m, atau km. Berat memakai g atau kg. Isi memakai ml atau l. Pikirkan besarnya, lalu sentuh satuan yang paling cocok.",
        "pilihan": "pilihan",
        "q1": "Mau mengukur panjang sedotan. Satuan apa yang cocok?",
        "c1": "cm",
        "c2": "m",
        "c3": "km",
        "c4": "kg",
        "q2": "Mau mengukur tinggi tiang bendera. Satuan apa yang cocok?",
        "c5": "l",
        "q3": "Mau mengukur jarak rumah ke kota sebelah. Satuan apa yang cocok?",
        "c6": "g",
        "q4": "Mau mengukur berat sebutir anggur. Satuan apa yang cocok?",
        "c7": "ml",
        "q5": "Mau mengukur berat sekarung beras. Satuan apa yang cocok?",
        "q6": "Mau mengukur isi sendok obat. Satuan apa yang cocok?",
        "q7": "Mau mengukur isi ember besar. Satuan apa yang cocok?",
        "q8": "Mau mengukur lebar penghapus. Satuan apa yang cocok?",
        "q9": "Mau mengukur panjang kolam renang. Satuan apa yang cocok?",
        "q10": "Mau mengukur berat semangka. Satuan apa yang cocok?",
        "q11": "Mau mengukur isi tutup botol. Satuan apa yang cocok?",
        "q12": "Mau mengukur berat selembar kertas. Satuan apa yang cocok?"
      },
      "en": {
        "judul": "Units for Measuring",
        "instruksi": "Length uses cm, m or km. Mass uses g or kg. Capacity uses ml or l. Think how big it is, then touch the best unit.",
        "pilihan": "choices",
        "q1": "You want to measure the length of a straw. Which unit fits?",
        "c1": "cm",
        "c2": "m",
        "c3": "km",
        "c4": "kg",
        "q2": "You want to measure the height of a flagpole. Which unit fits?",
        "c5": "l",
        "q3": "You want to measure the distance from home to the next town. Which unit fits?",
        "c6": "g",
        "q4": "You want to measure the mass of one grape. Which unit fits?",
        "c7": "ml",
        "q5": "You want to measure the mass of a sack of rice. Which unit fits?",
        "q6": "You want to measure the capacity of a medicine spoon. Which unit fits?",
        "q7": "You want to measure the capacity of a big bucket. Which unit fits?",
        "q8": "You want to measure the width of an eraser. Which unit fits?",
        "q9": "You want to measure the length of a swimming pool. Which unit fits?",
        "q10": "You want to measure the mass of a watermelon. Which unit fits?",
        "q11": "You want to measure the capacity of a bottle cap. Which unit fits?",
        "q12": "You want to measure the mass of a sheet of paper. Which unit fits?"
      }
    },
